// OUTCOME-GRADE-SCALE (Sprint-5.0, Tobias 2026-06-23)
// ═══════════════════════════════════════════════════════════
// Empirically anchored grade scale 0-100 derived from the NBA-careered
// pool's peak_wa quantiles (n=1,784). Coleman's tier labels are kept
// as the UX vocabulary (Generational/MVP, All-NBA Regular, etc.) so
// scouts familiar with that taxonomy read our board immediately.
//
// Build pipeline: data-pipeline/scripts/compute_outcome_grade.py
// Source mapping: data-pipeline/data/processed/grade_anchors.json
//                 (also copied to backend/data/processed/ for API access)
//
// Why empirical, not pinned-to-comparables: an NBA-Quant never imports
// another scaled metric without a reality check. peak_wa is a different
// blend than Coleman's grade (xRAPM-blend production over best-3-yr
// window vs career-anchored impact + accolades). 8/27 comparable tier-
// agreement in our validation run — the disagreements are methodological
// honesty: we surface them in the UI rather than force-fit anchors.
const OUTCOME_GRADE_TIERS = [
  // grade_lo / grade_hi from Coleman's scale 1:1.
  // wa_lo / wa_hi are empirical NBA-pool quantiles from compute_outcome_grade.py.
  {name:"Generational/MVP",        grade_lo:95, grade_hi:100, wa_lo:43.91,  wa_hi:68.88, color:"#1d4ed8",
   comparables:["Nikola Jokić","Luka Dončić","Stephen Curry"]},
  {name:"All-NBA Regular",         grade_lo:88, grade_hi:94,  wa_lo:31.47,  wa_hi:43.91, color:"#2563eb",
   comparables:["Anthony Edwards","Shai Gilgeous-Alexander","Jayson Tatum"]},
  {name:"Perennial All-Star",      grade_lo:80, grade_hi:87,  wa_lo:20.88,  wa_hi:31.47, color:"#3b82f6",
   comparables:["Trae Young","Jaylen Brown","Pascal Siakam"]},
  {name:"Fringe All-Star",         grade_lo:70, grade_hi:79,  wa_lo:15.09,  wa_hi:20.88, color:"#60a5fa",
   comparables:["De'Aaron Fox","LaMelo Ball","Mikal Bridges"]},
  {name:"Good Starter",            grade_lo:60, grade_hi:69,  wa_lo: 7.76,  wa_hi:15.09, color:"#22c55e",
   comparables:["Desmond Bane","OG Anunoby","Lauri Markkanen"]},
  {name:"Average Starter",         grade_lo:50, grade_hi:59,  wa_lo: 2.24,  wa_hi: 7.76, color:"#86efac",
   comparables:["Onyeka Okongwu","Deni Avdija","Buddy Hield"]},
  {name:"Impact Role Player",      grade_lo:40, grade_hi:49,  wa_lo:-0.37,  wa_hi: 2.24, color:"#fbbf24",
   comparables:["Obi Toppin","Bruce Brown","Kevin Huerter"]},
  {name:"Low-End Rotation/Bench",  grade_lo:20, grade_hi:39,  wa_lo:-1.82,  wa_hi:-0.37, color:"#f97316",
   comparables:["Dennis Smith Jr.","Frank Ntilikina","Cam Reddish"]},
  {name:"Non-Rotational Washout",  grade_lo:1,  grade_hi:19,  wa_lo:-8.64,  wa_hi:-1.82, color:"#ec4899",
   comparables:["James Wiseman","Jarrett Culver","Cam Whitmore"]},
];
// True Null tier: peak_wa = NaN / never NBA. grade = 0, color = neutral.
const OUTCOME_GRADE_TRUE_NULL = {name:"True Null (Never Played)", grade_lo:0, grade_hi:0, color:"#a78bfa"};

/** Map a peak_wa value to a 0-100 outcome grade via piecewise-linear
 *  interpolation within the empirical tier it falls into.
 *  Returns {grade, tier} where tier is one of the OUTCOME_GRADE_TIERS objects.
 */
function peakWaToOutcomeGrade(peakWa) {
  if (peakWa == null || !isFinite(peakWa)) {
    return {grade: 0, tier: OUTCOME_GRADE_TRUE_NULL};
  }
  for (const t of OUTCOME_GRADE_TIERS) {
    if (peakWa >= t.wa_lo && peakWa <= t.wa_hi) {
      const waSpan = Math.max(t.wa_hi - t.wa_lo, 1e-6);
      const frac = (peakWa - t.wa_lo) / waSpan;
      const grade = t.grade_lo + frac * (t.grade_hi - t.grade_lo);
      return {grade: Math.round(grade * 10) / 10, tier: t};
    }
  }
  // Above the very top (Joker tail outliers): clip at 100
  if (peakWa > OUTCOME_GRADE_TIERS[0].wa_hi) return {grade: 100, tier: OUTCOME_GRADE_TIERS[0]};
  // Below floor: clip at bottom-tier grade_lo
  const bot = OUTCOME_GRADE_TIERS[OUTCOME_GRADE_TIERS.length - 1];
  return {grade: bot.grade_lo, tier: bot};
}

/** Build the parameters of an asymmetric-gaussian outcome curve for a
 *  prospect, derived ENTIRELY from his existing ppwa-based model signals
 *  (no new metric invented). Returns null if not enough signal.
 *
 *  Curve anatomy follows Coleman's vocabulary:
 *    - peak  (= grade)  : most likely outcome    (mapped from ppwa)
 *    - lLimit / hLimit  : empirical p10 / p90    (mapped from ppwa ± 1.282σ)
 *    - skew             : leans right when upside > downside, left otherwise
 *
 *  Model signals consumed:
 *    p.ppwa | p.war        : projected peak Wins Added (point estimate)
 *    p.sigma | p.volatility: prediction-uncertainty (Gaussian width on peak_wa scale)
 *    p.tiers (Superstar / All-Star / ... / Negative) : calibrated tier probs
 *
 *  Implementation:
 *    grade-space asymmetric Gauss: σ_left = peak − lLimit, σ_right = hLimit − peak.
 *    Skew is encoded purely by the asymmetry of these two sigmas — when upside
 *    (P(Super)+P(AS)) outweighs downside (P(Negative)+P(Replacement)), we
 *    stretch the hLimit further; downside-tilt stretches lLimit further.
 *    Confidence (height) is inverse to total range — narrower = more confident.
 */
function buildOutcomeCurveParams(p) {
  if (!p) return null;
  const mu  = p.ppwa ?? p.war ?? p.pred_mu;
  if (mu == null || !isFinite(mu)) return null;
  const sig = Math.max(p.sigma ?? p.volatility ?? p.pred_sigma ?? 2.5, 0.5);

  // Step 1: grade-space landing position.
  const peakMap   = peakWaToOutcomeGrade(mu);
  const peak      = peakMap.grade;
  const tier      = peakMap.tier;

  // Step 2: empirical p10 / p90 in WA, then map to grade.
  // (1.282 ≈ z-score for the 10th / 90th percentile of a standard normal.)
  const lWa = mu - 1.282 * sig;
  const hWa = mu + 1.282 * sig;
  const lMap = peakWaToOutcomeGrade(lWa);
  const hMap = peakWaToOutcomeGrade(hWa);
  let lLimit = lMap.grade;
  let hLimit = hMap.grade;

  // Guarantee L < peak < H even at extreme tier edges
  if (lLimit > peak - 1) lLimit = Math.max(0,  peak - 1);
  if (hLimit < peak + 1) hLimit = Math.min(100,peak + 1);

  // Step 3: skew tilt — encoded by stretching one side.
  // Use tier-probs if available (cleaner than re-deriving from peak/sigma).
  const t = p.tiers || p.v2TierProbs || {};
  const pSuper  = Number(t.Superstar)    || 0;
  const pAllStar= Number(t["All-Star"])  || 0;
  const pRepl   = Number(t.Replacement)  || 0;
  const pNeg    = Number(t.Negative)     || 0;
  const upside   = (pSuper + pAllStar) / 100;
  const downside = (pRepl + pNeg) / 100;
  // skewSig in [-1, +1]. Positive → upside-tilt (right tail heavier).
  const skewSig = Math.max(-1, Math.min(1, upside - downside));

  // Apply asymmetric stretch: max 30 % of the half-range.
  const halfL = peak - lLimit;
  const halfR = hLimit - peak;
  const stretch = 0.30;
  if (skewSig > 0) {
    // upside tilt → push hLimit further out (cap at 100)
    hLimit = Math.min(100, peak + halfR * (1 + stretch * skewSig));
  } else if (skewSig < 0) {
    // downside tilt → push lLimit further down (floor at 0)
    lLimit = Math.max(0, peak - halfL * (1 + stretch * (-skewSig)));
  }

  // Step 4: confidence — narrower band = more confident.
  // Used downstream to size the peak height of the rendered curve.
  const range = hLimit - lLimit;
  const confidence = Math.max(0.2, Math.min(1.0, 1 - range / 80));

  // pNba: prefer the modeled probability, fall back to a rough lift from
  // pElite (consistent with ProjectionTab's existing fallback).
  const pNbaResolved = p.pNba != null
    ? p.pNba
    : (p.pElite != null ? Math.min(0.95, p.pElite + 0.25) : null);

  return {
    peak, lLimit, hLimit,
    tier,
    skew: skewSig,
    confidence,
    pNba: pNbaResolved,
    madeNba: p.madeNba || false,
    mu, sigma: sig,
  };
}

/** Sample an asymmetric Gaussian density at x (grade-space).
 *  Used to draw the SVG path of the outcome distribution.
 */
function asymmetricGaussianPdf(x, peak, sigmaLeft, sigmaRight) {
  const sigma = x < peak ? sigmaLeft : sigmaRight;
  const safeSigma = Math.max(sigma, 1e-3);
  const z = (x - peak) / safeSigma;
  return Math.exp(-0.5 * z * z);
}


// ═══════════════════════════════════════════════════════════
// MIXTURE-OF-GAUSSIANS OUTCOME ENGINE (Sprint-5.2)
// ═══════════════════════════════════════════════════════════
// Engine refactor: instead of a single asymmetric Gaussian centered on
// the ppWA-mapped grade, build a Gaussian MIXTURE on the 0-100 grade
// scale where each model tier (Superstar / All-Star / Starter / Role /
// Replacement / Negative) contributes one bump weighted by the
// calibrated tier-probability.
//
// Why mixture, not single Gaussian:
// - The calibrated tier-probabilities ARE the model's distribution. We
//   shouldn't throw them away to refit a Gaussian on ppWA + sigma.
// - Real NBA outcomes are categorical (each player lands in one tier).
//   A mixture follows that structure honestly.
// - Boom-or-bust profiles (high P(Star) AND high P(Negative)) show as
//   bimodal curves — instantly visible, where a single Gaussian would
//   average them out.
// - Tight high-confidence profiles show as tall narrow peaks because
//   nearly all mass concentrates in one tier-bump.
//
// Tier grade-anchors below position each bump at its tier band midpoint
// (model tiers ↔ our empirical Coleman grade bands):
//   Superstar    → grade 94 (Generational + All-NBA Regular bands)
//   All-Star     → grade 78 (Perennial + Fringe All-Star bands)
//   Starter      → grade 60 (Good + Average Starter bands)
//   Role Player  → grade 45 (Impact Role Player band)
//   Replacement  → grade 30 (Low-End Rotation/Bench band)
//   Negative     → grade 10 (Non-Rotational Washout band)
//
// Sigma per bump is roughly half the band width so 99% of the mass
// stays inside its tier band.
// Sprint-5.2b: Sigma straffer (≈ 0.6× alt) damit die Bumps spitzer
// werden — visuelle Versetzung der peaks zwischen Spielern wird stärker,
// statt dass alle Curves zu einer breiten Mitte verschmieren.
const MIXTURE_TIER_ANCHORS = [
  {key:"Superstar",   grade:94, sigma:3.5, color:"#1d4ed8", letter:"A"},
  {key:"All-Star",    grade:78, sigma:4.5, color:"#3b82f6", letter:"A"},
  {key:"Starter",     grade:60, sigma:5.0, color:"#22c55e", letter:"B"},
  {key:"Role Player", grade:45, sigma:3.5, color:"#fbbf24", letter:"C"},
  {key:"Replacement", grade:30, sigma:5.0, color:"#f97316", letter:"D"},
  {key:"Negative",    grade:10, sigma:4.5, color:"#ec4899", letter:"D"},
];

/** Evaluate the mixture density at grade x.
 *  components = [{center, sigma, weight}, ...] with weights summing to 1.
 */
function mixtureDensity(x, components) {
  let d = 0;
  for (const c of components) {
    const z = (x - c.center) / c.sigma;
    d += c.weight * Math.exp(-0.5 * z * z);
  }
  return d;
}

/** Sprint-5.2c: smooth outcome curve derived from the *moments* of the
 *  calibrated tier-probability distribution, instead of stacking fixed
 *  Gaussian bumps at every tier center.
 *
 *  Why the change: when you place one bump at each tier center (10, 30,
 *  45, 60, 78, 94) and a prospect has mass at 2-3 tiers, the rendered
 *  density shows 2-3 distinct modes — but those are ARTIFACTS of the
 *  discrete tier buckets, not real bimodal outcomes. Plus the visual
 *  modal lands on whichever tier has the most mass, never on the
 *  ppWA-mapped grade that we print in the row — they disagree by
 *  10-15 grade points for most multi-tier prospects.
 *
 *  New approach: compute the mixture's mean / variance / skewness on
 *  the grade scale, then render an asymmetric Gaussian whose peak sits
 *  at the printed (ppWA-mapped) grade and whose width + skew reflect
 *  the underlying tier distribution. One smooth curve per prospect,
 *  always centered on the printed Grade number.
 *
 *  Real boom-or-bust profiles are still rendered as bimodal — but only
 *  when the two heaviest tiers are far apart AND both meaningfully
 *  weighted AND neither dominates the distribution (strict triple gate
 *  documented in the bimodalDecision section). That keeps "bimodal"
 *  visually rare and informative when it does appear.
 *
 *  Output (same shape as before, with two new fields for the renderer):
 *    peakGrade     – ppWA-mapped grade (consistency with Projection tab)
 *    modalGrade    – same as peakGrade now (curve is centered there)
 *    medianGrade   – same as peakGrade now (curve is symmetric around it)
 *    lLimit/hLimit – peakGrade ± 1.282·sigmaLeft/Right (p10 / p90)
 *    sigmaLeft, sigmaRight – the asymmetric-Gauss render params
 *    isBimodal     – true only for genuine boom-or-bust profiles
 *    bimodalComponents – two-bump render data when isBimodal
 *    tier, predTier, tierLetter, confidence, pNba, madeNba, mu – as before
 */
function buildOutcomeCurveMixture(p) {
  if (!p) return null;
  const tiers = p.tiers || p.v2TierProbs || {};
  // Step 1 — extract & normalize tier weights ────────────────────────
  let totalProb = 0;
  const tierMass = MIXTURE_TIER_ANCHORS.map(a => {
    const w = Math.max(0, Number(tiers[a.key]) || 0) / 100;
    totalProb += w;
    return { ...a, weight: w };
  });
  if (totalProb < 0.01) return null;
  const norm = tierMass.map(t => ({ ...t, weight: t.weight / totalProb }));

  // Step 2 — moments of the tier-prob distribution on the grade scale ─
  // Mean (between-tier expected grade), between-tier variance,
  // total stddev (between + within), skewness.
  const probMean = norm.reduce((a, t) => a + t.weight * t.grade, 0);
  const betweenVar = norm.reduce((a, t) => a + t.weight * (t.grade - probMean) ** 2, 0);
  // Within-tier variance baseline — narrow tiers have ≈ ±6 grade-points
  // of natural spread inside the tier (smooths the gauss so the curve
  // doesn't collapse to a Dirac when one tier dominates 100%).
  const WITHIN_VAR = 36;
  const stddev = Math.sqrt(betweenVar + WITHIN_VAR);
  const skewness = stddev > 0
    ? norm.reduce((a, t) => a + t.weight * ((t.grade - probMean) / stddev) ** 3, 0)
    : 0;

  // Step 3 — peak grade = ppWA-mapped grade, CLAMPED to predTier band
  // (Sprint-5.2e). Both prior approaches missed the right constraint:
  //   - Sprint-5.2c used ppWA-mapped grade unconstrained → curve peak
  //     could fall outside the model's own tier verdict.
  //   - Sprint-5.2d used probMean (tier-prob distribution mean) → curve
  //     peak frequently landed in a different tier band than predTier,
  //     so the colour/comparables and the A/B/C/D letter disagreed.
  //
  // The model's predTier verdict (cumulative-threshold tier label) is
  // the source of truth for WHICH BAND the peak belongs to. ppWA then
  // sets the WITHIN-BAND position, giving real sub-tier differentiation.
  // When ppWA-mapped grade falls outside predTier's band, the peak is
  // clamped to the nearest band edge — that respects the model's tier
  // judgement while still using ppWA for ordering within the tier.
  //
  // Result: tier letter, displayed Grade, curve colour, comparables,
  // and visual peak position all agree with predTier. Sigma + skew
  // still come from the tier-prob moments (Step 5 below) so the curve
  // SHAPE reflects the underlying uncertainty / skew honestly.
  const TIER_PEAK_BANDS = {
    "Superstar":   {center: 94, lo: 88, hi: 100},
    "All-Star":    {center: 78, lo: 70, hi:  87},
    "Starter":     {center: 60, lo: 50, hi:  69},
    "Role Player": {center: 45, lo: 40, hi:  49},
    "Replacement": {center: 30, lo: 20, hi:  39},
    "Negative":    {center: 10, lo:  1, hi:  19},
  };
  const mu = p.ppwa ?? p.war ?? p.pred_mu;
  const predTierLabel = p.predTier || null;
  const band = predTierLabel && TIER_PEAK_BANDS[predTierLabel];

  // Sprint-5.5.J Phase 3e: removed tier-band clamping. peakGrade comes
  // DIRECTLY from ppwa-mapped grade so visual position is honest. Tier color
  // is derived from actual peakGrade band, not predTier. Real differentiation
  // between players in same modal tier.
  let peakGrade;
  if (mu != null && isFinite(mu)) {
    peakGrade = peakWaToOutcomeGrade(mu).grade;
  } else if (band) {
    peakGrade = band.center;
  } else {
    peakGrade = probMean;
  }
  // Tier derived from peakGrade band so the colour + comparables line
  // up with where the peak actually sits (which is inside predTier's
  // band by construction).
  let tier = OUTCOME_GRADE_TIERS[OUTCOME_GRADE_TIERS.length - 1];
  for (const t of OUTCOME_GRADE_TIERS) {
    if (peakGrade >= t.grade_lo && peakGrade <= t.grade_hi) { tier = t; break; }
  }

  // Step 4 — bimodal decision (strict triple gate so it stays rare) ──
  const ranked = norm.slice().sort((a, b) => b.weight - a.weight);
  const top1 = ranked[0];
  const top2 = ranked[1];
  const tierDistance = Math.abs(top1.grade - top2.grade);
  const isBimodal = (
    top2.weight > 0.18 &&        // 2nd heaviest carries meaningful mass
    tierDistance > 28 &&         // and is far from the 1st heaviest
    top1.weight < 0.55           // and 1st doesn't dominate the distribution
  );

  // Step 5 — Beta(α, β) fit on [0, 100] via Method of Moments ────────
  // (Sprint-5.3.1: use LOCAL-NEIGHBOURHOOD moments instead of the full
  // 6-tier distribution.)
  //
  // Why local: when predTier is a cumulative-threshold verdict (e.g.
  // "All-Star" because P(All-Star+) clears 18% even though modal mass
  // sits in Starter), the full-distribution variance is huge — it
  // includes mass from far-distant tiers like Negative or Superstar.
  // Beta fitted to that variance produces a long-tailed curve that
  // visually says "ultimate boom-or-bust" when the mass is really
  // concentrated around 2-3 adjacent tiers.
  //
  // Local neighbourhood = predTier ± 1 (3 tiers max, edge cases use 2).
  // Re-normalize masses within those tiers, then compute local moments.
  // This gives the spread of plausible outcomes around the model's
  // verdict, ignoring far-tier noise that pulls the variance up.
  //
  // Cap on the resulting stddev: 1.2 × half-band-width of predTier, so
  // even when local-mass is well-spread, the curve mostly stays inside
  // the verdict band with at most modest spillover into neighbours.
  // True non-adjacent boom-or-bust still gets the bimodal renderer
  // (Step 4 triple gate) — the local-Beta is for the unimodal path.
  const TIER_ORDER_LH = ["Negative", "Replacement", "Role Player",
                         "Starter", "All-Star", "Superstar"];
  let localKeys;
  if (predTierLabel && TIER_ORDER_LH.includes(predTierLabel)) {
    const idx = TIER_ORDER_LH.indexOf(predTierLabel);
    localKeys = TIER_ORDER_LH.slice(Math.max(0, idx-1), Math.min(6, idx+2));
  } else {
    localKeys = TIER_ORDER_LH;
  }
  const localMass = norm.filter(t => localKeys.includes(t.key));
  const localTotal = localMass.reduce((a, t) => a + t.weight, 0);
  let localStddev = stddev; // fallback to full-distribution stddev
  if (localTotal > 0.01) {
    const localNorm = localMass.map(t => ({ ...t, weight: t.weight / localTotal }));
    const localMean = localNorm.reduce((a, t) => a + t.weight * t.grade, 0);
    const localBetweenVar = localNorm.reduce((a, t) =>
      a + t.weight * (t.grade - localMean) ** 2, 0);
    const LOCAL_WITHIN_VAR = 16; // smaller within-tier baseline (≈ ±4 grade points spread inside a single tier)
    localStddev = Math.sqrt(localBetweenVar + LOCAL_WITHIN_VAR);
  }
  // Cap so the curve stays meaningfully concentrated in predTier's band
  // — extreme spread is the BIMODAL renderer's job, not the unimodal one
  const bandHalfWidth = band ? (band.hi - band.lo) / 2 : 12;
  const cappedStddev = Math.max(3, Math.min(localStddev, bandHalfWidth * 1.2));
  const betaFit = fitBetaMoM(peakGrade, cappedStddev);

  // Real Beta-CDF quantiles (no Normal approximation).
  const quants = betaQuantiles(betaFit.alpha, betaFit.beta, [0.10, 0.50, 0.90]);
  const lLimit = quants[0.10];
  const medianGrade = quants[0.50];
  const hLimit = quants[0.90];

  // Step 6 — bimodal Beta-mixture (only for genuine boom-or-bust) ────
  let bimodalBeta = null;
  if (isBimodal) {
    // Two narrow Betas, one at each heaviest tier center. Sigma 7 keeps
    // each component tight enough that both modes are visible.
    const b1 = fitBetaMoM(top1.grade, 7);
    const b2 = fitBetaMoM(top2.grade, 7);
    bimodalBeta = {
      components: [
        { alpha: b1.alpha, beta: b1.beta, weight: top1.weight, center: top1.grade },
        { alpha: b2.alpha, beta: b2.beta, weight: top2.weight, center: top2.grade },
      ],
    };
  }

  // Step 7 — confidence ──────────────────────────────────────────────
  // Narrower curve = more confident. 50 grade-points range = 0 conf,
  // 0 range = 1 conf. Floored at 0.15 so the rendered peak height
  // stays visible even for very wide curves.
  const range = hLimit - lLimit;
  const confidence = Math.max(0.15, Math.min(1.0, 1 - range / 50));

  // Step 8 — tier letter from MODEL's predTier (not peak-grade band)
  const predTier = p.predTier || null;
  const letterMap = {
    "Superstar":"A", "All-Star":"A",
    "Starter":"B",
    "Role Player":"C",
    "Replacement":"D", "Negative":"D",
  };
  const tierLetter = predTier ? (letterMap[predTier] || "D")
                    : peakGrade >= 70 ? "A" : peakGrade >= 50 ? "B"
                    : peakGrade >= 40 ? "C" : "D";

  // Step 9 — pNba fallback for caveat strip ──────────────────────────
  const pNbaResolved = p.pNba != null
    ? p.pNba
    : (p.pElite != null ? Math.min(0.95, p.pElite + 0.25) : null);

  return {
    peakGrade,
    modalGrade:  peakGrade,
    medianGrade,
    lLimit, hLimit,
    // Sprint-5.3: Beta-distribution params replace asymmetric Gauss sigmas
    betaFit,
    bimodalBeta,
    isBimodal,
    tier,
    predTier,
    tierLetter,
    confidence,
    pNba: pNbaResolved,
    madeNba: p.madeNba || false,
    mu,
    // Diagnostic moments for tooltips / future use
    probMean, stddev, skewness,
    // Tier-prob breakdown (footer or hover detail)
    components: norm.filter(c => c.weight > 0.001).map(c => ({
      key: c.key, center: c.grade, weight: c.weight, color: c.color,
    })),
  };
}

/** Unified density evaluator used by all curve renderers. Handles the
 *  smooth (single-Beta) case and the bimodal (two-Beta mixture) case
 *  from the same params object so the renderer stays branch-free.
 *  Sprint-5.3: Beta(α, β) on [0, 100] replaces the prior asymmetric-Gauss.
 */
function outcomeCurveDensity(x, params) {
  if (params.isBimodal && params.bimodalBeta) {
    let d = 0;
    for (const c of params.bimodalBeta.components) {
      d += c.weight * betaPdfRaw(x, c.alpha, c.beta);
    }
    return d;
  }
  if (params.betaFit) {
    return betaPdfRaw(x, params.betaFit.alpha, params.betaFit.beta);
  }
  return 0;
}


// ═══════════════════════════════════════════════════════════
// SPRINT-5.3 BETA-DISTRIBUTION ENGINE (state-of-the-art)
// ═══════════════════════════════════════════════════════════
// Method-of-Moments Beta(α, β) fit on [0, 100] is the mathematically
// principled distribution for bounded outcomes. Natural skew comes from
// α/β asymmetry without any ad-hoc skew constants. p10 / p90 are the
// real Beta-CDF quantiles, not Normal-distribution approximations on an
// asymmetric Gauss.

/** Fit Beta(α, β) to a target mean and standard deviation on [0, 100]
 *  via method of moments. Returns the {alpha, beta} parameters.
 *  Constraint: variance < mean × (1 − mean) for a valid Beta — when
 *  violated, the variance is capped to 95% of the feasibility boundary
 *  rather than failing.
 */
function fitBetaMoM(targetMean, targetStd) {
  const mu = Math.max(0.001, Math.min(0.999, targetMean / 100));
  const maxVar = mu * (1 - mu);
  let varScaled = Math.pow(Math.max(targetStd, 0.5) / 100, 2);
  if (varScaled >= maxVar * 0.99) varScaled = maxVar * 0.95;
  const concentration = (mu * (1 - mu) / varScaled) - 1;
  if (concentration <= 0 || !isFinite(concentration)) {
    return { alpha: 1, beta: 1 };
  }
  return {
    alpha: Math.max(0.5, mu * concentration),
    beta:  Math.max(0.5, (1 - mu) * concentration),
  };
}

/** Unnormalized Beta PDF on [0, 100]. We work in log-space to handle
 *  large α, β without overflow, then exp at the end. The renderer
 *  normalizes by maxY so the absolute scale doesn't matter.
 */
function betaPdfRaw(x, alpha, beta) {
  if (x <= 0.01 || x >= 99.99) return 0;
  const y = x / 100;
  return Math.exp((alpha - 1) * Math.log(y) + (beta - 1) * Math.log(1 - y));
}

/** Compute multiple quantiles of a Beta distribution via numerical
 *  trapezoidal integration of the unnormalized PDF (401 sample points).
 *  Returns an object keyed by the requested quantile values.
 */
function betaQuantiles(alpha, beta, qList) {
  const N = 400;
  const dens = new Array(N + 1);
  let total = 0;
  for (let i = 0; i <= N; i++) {
    const x = (i / N) * 100;
    const d = betaPdfRaw(x, alpha, beta);
    dens[i] = d;
    total += d;
  }
  const out = {};
  const sorted = qList.slice().sort((a, b) => a - b);
  if (total <= 0) {
    for (const q of sorted) out[q] = q * 100;
    return out;
  }
  let cum = 0, qIdx = 0;
  for (let i = 0; i <= N && qIdx < sorted.length; i++) {
    cum += dens[i];
    while (qIdx < sorted.length && cum / total >= sorted[qIdx]) {
      out[sorted[qIdx]] = (i / N) * 100;
      qIdx++;
    }
  }
  while (qIdx < sorted.length) { out[sorted[qIdx]] = 100; qIdx++; }
  return out;
}


// Fallback wenn pos_detailed (PG/SG/SF/PF/C) fehlt — leite aus pos + height ab.
// Wird genutzt für historische / intl Spieler ohne BartTorvik-role.
function inferDetailedPos(pos3, htIn, astP) {
  const h = htIn || 78;
  const a = astP || 0;
  if (pos3 === "Playmaker") return (h <= 76 && a >= 22) ? "PG" : (h <= 76 ? "PG" : "SG");
  if (pos3 === "Big")       return (h >= 83 ? "C" : "PF");
  // Wing
  if (h <= 78) return "SG";
  if (h <= 80) return "SF";
  if (h <= 82) return "SF";  // Tall Wings
  return "PF";
}

